-- Ukrainian locale.  The translation tables are rebuilt because SQLite does not
-- support changing a CHECK constraint in place.  Every column, key, foreign key
-- and existing row is copied verbatim before the new locale is added.

PRAGMA foreign_keys = OFF;

CREATE TABLE demand_translations_uk (
  demand_id INTEGER NOT NULL REFERENCES demands(id) ON DELETE CASCADE,
  locale TEXT NOT NULL CHECK (locale IN ('he','ar','yi','ru','en','am','uk')),
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  rationale TEXT,
  verification TEXT,
  exceptions TEXT,
  PRIMARY KEY (demand_id, locale)
);
INSERT INTO demand_translations_uk SELECT * FROM demand_translations;
DROP TABLE demand_translations;
ALTER TABLE demand_translations_uk RENAME TO demand_translations;

CREATE TABLE message_templates_uk (
  id INTEGER PRIMARY KEY,
  locale TEXT NOT NULL CHECK (locale IN ('he','ar','yi','ru','en','am','uk')),
  channel TEXT NOT NULL CHECK (channel IN ('email','whatsapp','social')),
  subject TEXT,
  body TEXT NOT NULL,
  UNIQUE (locale, channel)
);
INSERT INTO message_templates_uk SELECT * FROM message_templates;
DROP TABLE message_templates;
ALTER TABLE message_templates_uk RENAME TO message_templates;

CREATE TABLE recipient_translations_uk (
  recipient_id INTEGER NOT NULL REFERENCES recipients(id) ON DELETE CASCADE,
  locale TEXT NOT NULL CHECK (locale IN ('he','ar','yi','ru','en','am','uk')),
  name TEXT NOT NULL,
  PRIMARY KEY (recipient_id, locale)
);
INSERT INTO recipient_translations_uk SELECT * FROM recipient_translations;
DROP TABLE recipient_translations;
ALTER TABLE recipient_translations_uk RENAME TO recipient_translations;

CREATE TABLE plan_item_translations_uk (
  plan_item_id INTEGER NOT NULL REFERENCES plan_items(id) ON DELETE CASCADE,
  locale TEXT NOT NULL CHECK (locale IN ('he','ar','yi','ru','en','am','uk')),
  title TEXT NOT NULL,
  decision TEXT NOT NULL,
  instrument TEXT NOT NULL,
  owners TEXT NOT NULL,
  criterion TEXT NOT NULL,
  PRIMARY KEY (plan_item_id, locale)
);
INSERT INTO plan_item_translations_uk SELECT * FROM plan_item_translations;
DROP TABLE plan_item_translations;
ALTER TABLE plan_item_translations_uk RENAME TO plan_item_translations;

CREATE TABLE portfolio_translations_uk (
  portfolio_id INTEGER NOT NULL REFERENCES portfolios(id) ON DELETE CASCADE,
  locale TEXT NOT NULL CHECK (locale IN ('he','ar','yi','ru','en','am','uk')),
  name TEXT NOT NULL,
  PRIMARY KEY (portfolio_id, locale)
);
INSERT INTO portfolio_translations_uk SELECT * FROM portfolio_translations;
DROP TABLE portfolio_translations;
ALTER TABLE portfolio_translations_uk RENAME TO portfolio_translations;

PRAGMA foreign_keys = ON;

INSERT OR IGNORE INTO demand_translations
  (demand_id, locale, title, body, rationale, verification, exceptions) VALUES
 (1,'uk','Вибори у встановлений строк','Партія зобов’язується не підтримувати продовження повноважень Кнесету, крім випадку, коли вимоги Основного закону виконано: спеціальний закон ухвалено щонайменше 80 депутатами за виняткових обставин, які фактично унеможливлюють своєчасні вибори. Закон одночасно визначає нову дату виборів.','Війна чи надзвичайний стан не повинні автоматично давати чинній владі безстрокове продовження повноважень.','Публічна позиція партії; голосування депутатів; текст законопроєкту; нова дата; обґрунтування неможливості провести вибори.','Коротке перенесення допустиме лише за доведеної неможливості забезпечити доступне й безпечне голосування.'),
 (2,'uk','Визнання результатів і законної процедури','Партія зобов’язується визнавати офіційно оприлюднені результати, користуватися лише передбаченими законом способами оскарження, приймати остаточні рішення компетентних виборчих і судових органів та забезпечувати мирну й своєчасну передачу влади.','Виборча система працює лише тоді, коли всі учасники приймають спільну процедуру, навіть за несприятливого результату.','Офіційні заяви; подані скарги; дії після оприлюднення результатів; участь у передачі повноважень.','Можна оскаржувати конкретні порушення та вимагати перерахунку в порядку, встановленому законом, але не відмовлятися від виборів загалом.'),
 (3,'uk','Виконання остаточних судових рішень','Партія зобов’язується не підтримувати уряд, який оголошує остаточне судове рішення необов’язковим, наказує посадовцям діяти всупереч судовому наказу або використовує надзвичайні повноваження для скасування конкретного рішення. До зміни рішення уряд діє відповідно до чинного наказу.','Право на судовий захист втрачає сенс, якщо держава сама обирає, які рішення виконувати.','Зміст урядових рішень; вказівки державним органам; строки виконання; офіційні заяви про перегляд чи відстрочку.','Законні процесуальні дії допустимі, якщо вони не зупиняють рішення автоматично, якщо суд не постановив інакше.'),
 (4,'uk','Розкриття можливих коаліцій','До виборів партія публікує, з ким готова формувати уряд, з ким допускає угоду про зовнішню підтримку, які коаліції виключає, кого рекомендуватиме для формування уряду та які умови вважає обов’язковими.','Громадянин голосує не лише за програму, а й за можливий склад виконавчої влади.','Офіційний документ партії; рекомендації президенту; коаліційні переговори; остаточна угода.','Зміна позиції можлива за істотної зміни обставин, але її причини та оновлену позицію слід публічно пояснити до остаточного рішення.'),
 (5,'uk','Обмеження розміру уряду','Партія зобов’язується підтримувати уряд не більш як із 18 міністрів, включно з прем’єр-міністром, і чотирьох заступників міністрів. Це добровільне політичне обмеження.','Кількість посад має визначатися завданнями управління, а не потребою розподіляти символічні титули.','Склад уряду; кількість заступників; затверджена структура міністерств; бюджети апаратів.','Тимчасове перевищення можливе до шести місяців із публічним обґрунтуванням і вартістю, без створення постійного нового апарату.'),
 (6,'uk','Відмова від міністрів без виконавчої відповідальності','Партія зобов’язується не призначати міністрів без визначеної сфери відповідальності, законних повноважень, підзвітного державного апарату та оприлюднених цілей і показників роботи.','Кожна міністерська посада повинна мати чітку суспільну функцію.','Для кожного міністра публікуються повноваження, підпорядковані підрозділи, бюджет, чисельність апарату та цілі на рік.','Допустимий тимчасовий координатор у секретаріаті прем’єр-міністра без окремого міністерства, бюджету чи дублювання повноважень.'),
 (7,'uk','Програма перших 100 днів','До виборів партія публікує перелік дій, які просуватиме в перші 100 днів участі в уряді. Для кожної дії зазначаються рішення, строк, відповідальний орган, потрібне законодавство, відомі бюджетні наслідки та критерій виконання.','Загальна декларація не дає змоги оцінити готовність партії до управління.','Після формування уряду публікується відкритий трекер зі статусами: не розпочато, у роботі, виконано, змінено, відкладено з поясненням.','Строк можна змінити через об’єктивну перешкоду; причина, новий строк і відповідальний орган мають бути оприлюднені.'),
 (8,'uk','Державна слідча комісія щодо подій 7 жовтня','Партія зобов’язується підтримати рішення уряду про створення державної слідчої комісії відповідно до закону. Комісія має охопити особисті й системні причини провалу, а рішення про її створення слід ухвалити не пізніше ніж через 14 днів після формування уряду.','Розслідування має охоплювати всі відповідні рівні влади, не виключаючи їх наперед.','Рішення уряду; офіційний мандат; оприлюднення призначень; повноваження та ресурси комісії.','Таємні матеріали розглядаються у захищеному законом режимі, але секретність не може виключити з розслідування цілу категорію рішень.'),
 (9,'uk','Непартійне використання поліції, армії та служб безпеки','Партія визнає законний цивільний контроль обраного уряду над безпековою системою та зобов’язується не використовувати силові органи для партійної агітації, не втручатися в окремі розслідування поза межами закону й призначати керівників за оприлюдненими професійними критеріями.','Професійна незалежність не скасовує демократичного нагляду, але силові органи не мають ставати інструментом окремого політика чи партії.','Офіційні директиви; процедури призначень; висновки комісій; втручання у справи; рішення судів і правових органів.','Уряд і уповноважені міністри зберігають стратегічні, бюджетні та кадрові повноваження, надані законом.'),
 (10,'uk','Публічність коаліційних і бюджетних зобов’язань','Партія зобов’язується публікувати коаліційні угоди та додатки, домовленості про посади, додаткові бюджетні асигнування, критерії розподілу коштів і передбачувані джерела фінансування.','Виборець має розуміти не лише склад коаліції, а й ціну укладених угод.','Оприлюднені угоди; державний бюджет; рішення фінансових комітетів; бюджетні трансферти.','Тимчасово можна не розкривати лише інформацію, що створює конкретний безпековий ризик або порушує захищену законом приватність; підставу слід зазначити.'),
 (11,'uk','Спільний механізм висунення кандидата','До виборів підписанти обирають і публікують один механізм: лідер партії з найбільшою кількістю мандатів, заздалегідь погоджений кандидат, кандидат із найбільшою кількістю обов’язкових рекомендацій або інша оприлюднена формула. Механізм має передбачати заміну кандидата за юридичної неможливості, добровільної відмови, смерті чи тяжкої хвороби.',NULL,NULL,NULL),
 (12,'uk','Протокол ризику неподолання виборчого бар’єра','Чинний виборчий бар’єр становить 3,25% дійсних голосів. До кінцевого строку подання списків підписанти публікують спільний протокол для партій, стабільно близьких до бар’єра або нижче нього. Протокол заздалегідь визначає опитування, період, спосіб обчислення середнього, похибку, відповідального за рішення та можливі варіанти. Платформа не визначає автоматично, яка партія має знятися.',NULL,NULL,NULL),
 (13,'uk','Заборона угод, що суперечать оприлюдненій угоді','Підписант не укладає таємної угоди, яка порушує оприлюднену коаліційну карту, обходить спільний механізм кандидата, дає іншій стороні право одноосібно скасувати угоду або приховує розподіл посад чи бюджетні зобов’язання. Конфіденційність переговорів допустима, але остаточні зобов’язання публікуються до голосування про довіру уряду.',NULL,NULL,NULL),
 (14,'uk','Процедура врегулювання спорів','Підписанти заздалегідь визначають представників для переговорів, строк розгляду спору, питання для одностайного рішення, питання для рішення більшістю, незалежного посередника або погоджений орган і порядок публічного повідомлення про вихід з угоди. Одна сторона не повинна блокувати всю коаліцію у питанні, яке заздалегідь не оголошено обов’язковим.',NULL,NULL,NULL),
 (15,'uk','Мінімальна спільна програма','Підписанти домовляються лише про обмежений пакет: законну передачу влади, розслідування подій 7 жовтня, структуру уряду, бюджетну прозорість, правила державної служби, перші заходи безпеки та економічної стабільності й процедуру розгляду спірних ідеологічних питань. Розбіжності щодо довгострокового устрою, територій, релігії та економічної моделі можуть зберігатися за наявності законної процедури рішень.',NULL,NULL,NULL);

