UPDATE demand_translations SET
 title='Вибори у встановлений строк',
 body='Партія зобов’язується не підтримувати продовження строку повноважень Кнесету, крім випадку, що відповідає вимогам Основного закону: ухвалення спеціального закону більшістю щонайменше 80 депутатів за особливих обставин, які фактично перешкоджають проведенню виборів у строк. Продовження не повинно перевищувати період, об’єктивно необхідний через такі обставини, а той самий закон має одночасно визначити нову дату виборів.',
 rationale='Війна або надзвичайна ситуація не повинні автоматично надавати чинній владі невизначене продовження повноважень.',
 verification='Оприлюднена позиція партії; голосування депутатів; текст запропонованого закону; конкретна нова дата; обґрунтування об’єктивної неможливості голосування.',
 exceptions='Коротке перенесення допустиме лише за реальної неможливості забезпечити доступне й безпечне голосування. Політична недоцільність, несприятливі опитування або сам факт тривалої воєнної операції не є достатньою підставою без доведеної неможливості провести вибори.'
 WHERE demand_id=1 AND locale='uk';
UPDATE demand_translations SET
 title='Визнання результатів і законної процедури',
 body='Партія зобов’язується визнавати офіційно оприлюднені результати, використовувати лише передбачені законом способи оскарження, приймати остаточні рішення компетентних виборчих і судових органів та забезпечувати мирну й своєчасну передачу влади.',
 rationale='Виборча система працює лише тоді, коли всі учасники приймають спільну процедуру, зокрема за несприятливого для себе результату.',
 verification='Офіційні заяви; зміст поданих скарг; дії після оприлюднення результатів; участь у передачі повноважень.',
 exceptions='Партія може оскаржувати конкретні порушення та вимагати перерахунку в установленому законом порядку. До остаточного рішення спір не можна використовувати як підставу для загальної відмови визнавати вибори.'
 WHERE demand_id=2 AND locale='uk';
UPDATE demand_translations SET
 title='Виконання остаточних судових рішень',
 body='Партія зобов’язується не підтримувати уряд, який заявляє, що остаточне судове рішення не є обов’язковим, доручає посадовцям діяти всупереч судовому наказу або застосовує надзвичайні повноваження для скасування конкретного судового рішення. Уряд може просити суд про роз’яснення, перегляд або відстрочку, але до зміни рішення діє відповідно до чинного наказу.',
 rationale='Право на судовий захист втрачає сенс, якщо держава самостійно вирішує, які рішення виконувати.',
 verification='Зміст урядових рішень; вказівки державним органам; строки виконання судових наказів; офіційні звернення про відстрочку або перегляд.',
 exceptions='Допустимі законні процесуальні дії, які не зупиняють рішення автоматично, якщо суд не постановив інакше.'
 WHERE demand_id=3 AND locale='uk';
UPDATE demand_translations SET
 title='Розкриття можливих коаліцій',
 body='До виборів партія публікує: з якими партіями вона готова формувати уряд; з якими партіями допускає угоду про зовнішню підтримку; які коаліційні комбінації виключає; кого готова рекомендувати для формування уряду; і які умови вважає обов’язковими для своєї участі.',
 rationale='Громадянин голосує не лише за партійну програму, а й за можливий склад виконавчої влади.',
 verification='Офіційний документ партії; рекомендації президенту; коаліційні переговори; остаточна коаліційна угода.',
 exceptions='Позиція може змінитися за істотної зміни обставин, але партія має публічно пояснити зміну, назвати нові обставини, отримати схвалення уповноваженого партійного органу та оприлюднити оновлену позицію до ухвалення остаточного рішення.'
 WHERE demand_id=4 AND locale='uk';
UPDATE demand_translations SET
 title='Обмеження розміру уряду',
 body='Партія зобов’язується підтримувати уряд, що складається не більш як із 18 міністрів, включно з прем’єр-міністром, і чотирьох заступників міністрів. Це добровільне політичне обмеження. Чинний Основний закон дозволяє призначати міністра без портфеля й не встановлює запропонованої проєктом максимальної кількості.',
 rationale='Кількість посад має визначатися завданнями управління, а не потребою розподіляти символічні посади.',
 verification='Склад уряду; кількість заступників; затверджена структура міністерств; бюджети апаратів.',
 exceptions='Тимчасове перевищення можливе лише на строк не більш як шість місяців, за наявності оприлюдненого професійного обґрунтування, оприлюдненої вартості, підтримки щонайменше 70 депутатів і без створення нового постійного апарату до окремого рішення. Поріг у 70 депутатів є запропонованою політичною умовою, а не чинною вимогою закону.'
 WHERE demand_id=5 AND locale='uk';
UPDATE demand_translations SET
 title='Відмова від міністрів без виконавчої відповідальності',
 body='Партія зобов’язується не призначати міністрів без визначеної сфери відповідальності, законних повноважень, підзвітного державного апарату та оприлюднених цілей і показників роботи. Пропонується не використовувати передбачену законом можливість призначати міністрів без портфеля.',
 rationale='Кожна міністерська посада повинна мати зрозумілу суспільну функцію.',
 verification='Для кожного міністра публікуються: повноваження; підпорядковані підрозділи; бюджет; чисельність апарату; цілі на рік.',
 exceptions='Допускається тимчасовий координатор у секретаріаті прем’єр-міністра без окремого міністерства, окремого постійного бюджету та дублювання повноважень.'
 WHERE demand_id=6 AND locale='uk';
UPDATE demand_translations SET
 title='Програма перших 100 днів',
 body='До виборів партія публікує перелік дій, які просуватиме в перші 100 днів участі в уряді. Для кожної дії зазначаються: рішення; строк; відповідальний орган; необхідне законодавство; відомі бюджетні наслідки; критерій виконання.',
 rationale='Загальна декларація не дає змоги оцінити готовність партії до управління.',
 verification='Після формування уряду публікується відкритий трекер зі статусами: не розпочато; у роботі; виконано; змінено; відкладено з поясненням.',
 exceptions='Строк може бути змінено через об’єктивну перешкоду. Причина, новий строк і відповідальний орган мають бути оприлюднені.'
 WHERE demand_id=7 AND locale='uk';
UPDATE demand_translations SET
 title='Державна слідча комісія щодо подій 7 жовтня',
 body='Партія зобов’язується підтримати рішення уряду про створення державної слідчої комісії відповідно до Закону про слідчі комісії. За чинним механізмом уряд вирішує питання створення комісії та визначає предмет розслідування, після чого голова Верховного суду призначає голову й інших членів комісії. Запропонований строк: рішення уряду ухвалюється не пізніше ніж через 14 днів після його формування.',
 rationale='Розслідування має охоплювати особисті й системні причини провалу, не виключаючи наперед цілі рівні влади.',
 verification='Рішення уряду; формально визначений мандат; оприлюднення призначень; повноваження й ресурси комісії. Мінімальний предмет: політичний рівень; армія та військова розвідка; ШАБАК та інші розвідувальні служби; поліція; цивільна оборона й готовність тилу; процеси обміну інформацією; підготовка до загрози; ухвалення рішень після початку нападу.',
 exceptions='Таємні матеріали розглядаються у передбаченому законом захищеному режимі. Таємність не повинна використовуватися для виключення з розслідування цілої категорії рішень.'
 WHERE demand_id=8 AND locale='uk';
UPDATE demand_translations SET
 title='Непартійне використання поліції, армії та служб безпеки',
 body='Партія визнає законний цивільний контроль обраного уряду над системою безпеки та водночас зобов’язується: не використовувати силові органи для партійної агітації; не втручатися в конкретні кримінальні розслідування інакше, ніж у межах закону; не вказувати, як поліція має ставитися до конкретного протесту чи політичної групи; не ставити просування офіцерів у залежність від партійної лояльності; здійснювати призначення керівників за оприлюдненими професійними критеріями; документувати загальні політичні директиви; зберігати професійну оцінку командування та розвідувальних органів.',
 rationale='Професійна самостійність не скасовує демократичного нагляду, але силові органи не повинні перетворюватися на інструмент конкретного політика чи партії.',
 verification='Офіційні директиви; процедура призначень; висновки комісій; втручання в конкретні справи; рішення суду та правових органів.',
 exceptions='Уряд і уповноважені міністри зберігають усі надані законом стратегічні, бюджетні та кадрові повноваження.'
 WHERE demand_id=9 AND locale='uk';
UPDATE demand_translations SET
 title='Публічність коаліційних і бюджетних зобов’язань',
 body='Партія зобов’язується публікувати: коаліційні угоди; додатки; зобов’язання щодо посад; додаткові бюджетні асигнування; критерії розподілу коштів; передбачувані джерела фінансування.',
 rationale='Виборець має розуміти не лише склад коаліції, а й ціну укладених угод.',
 verification='Оприлюднені угоди; державний бюджет; рішення фінансових комітетів; бюджетні трансферти.',
 exceptions='Тимчасово можна не публікувати лише інформацію, розкриття якої створює конкретний безпековий ризик або порушує захищену законом приватну інформацію. Підставу слід зазначити.'
 WHERE demand_id=10 AND locale='uk';
UPDATE demand_translations SET
 title='Спільний механізм висунення кандидата',
 body='До виборів підписанти обирають і публікують один механізм: лідер партії-підписанта з найбільшою кількістю мандатів; заздалегідь погоджений кандидат; кандидат, який отримав найбільшу кількість обов’язкових рекомендацій підписантів; або інша заздалегідь оприлюднена формула. Механізм має містити процедуру заміни кандидата в разі юридичної неможливості, добровільної відмови, смерті чи тяжкої хвороби.',
 rationale=NULL, verification=NULL, exceptions=NULL
 WHERE demand_id=11 AND locale='uk';
UPDATE demand_translations SET
 title='Протокол ризику неподолання виборчого бар’єра',
 body='Чинний виборчий бар’єр становить 3,25% дійсних голосів. Підписанти зобов’язуються до кінцевого строку подання списків опублікувати спільний протокол для партій, які стабільно перебувають біля чинного бар’єра або нижче нього. Протокол має заздалегідь визначити: які публічні опитування враховуються; за який період; як обчислюється середнє; яка похибка використовується; хто ухвалює рішення; які варіанти розглядаються — спільний список, об’єднання, відмова від участі або окрема участь із публічним обґрунтуванням. Платформа автоматично не визначає, яка партія має знятися, і не оголошує голоси за неї втраченими до офіційних результатів.',
 rationale=NULL, verification=NULL, exceptions=NULL
 WHERE demand_id=12 AND locale='uk';
UPDATE demand_translations SET
 title='Заборона угод, що суперечать оприлюдненій угоді',
 body='Підписант не укладає таємної угоди, яка порушує оприлюднену коаліційну карту, обходить спільний механізм кандидата, надає іншій стороні право одноосібно скасувати угоду або приховує розподіл посад чи бюджетні зобов’язання. Конфіденційність переговорного процесу допустима. Остаточні зобов’язання публікуються до голосування про довіру уряду.',
 rationale=NULL, verification=NULL, exceptions=NULL
 WHERE demand_id=13 AND locale='uk';
UPDATE demand_translations SET
 title='Процедура врегулювання спорів',
 body='Підписанти заздалегідь визначають: представників для переговорів; строк розгляду спору; коло питань, що потребують одностайності; коло питань, що вирішуються більшістю; незалежного посередника або погоджений орган; порядок публічного повідомлення про вихід з угоди. Угода не повинна дозволяти одному учаснику блокувати всю коаліцію з питання, яке заздалегідь не було оголошене обов’язковим.',
 rationale=NULL, verification=NULL, exceptions=NULL
 WHERE demand_id=14 AND locale='uk';
UPDATE demand_translations SET
 title='Мінімальна спільна програма',
 body='Підписанти зобов’язуються погодити лише обмежений пакет: законну передачу влади; розслідування подій 7 жовтня; структуру уряду; бюджетну прозорість; правила державної служби; перші заходи безпеки та економічної стабільності; процедуру розгляду спірних ідеологічних питань. Розбіжності щодо довгострокового врегулювання, територій, релігії та економічної моделі можуть зберігатися, якщо визначено законну процедуру ухвалення рішень.',
 rationale=NULL, verification=NULL, exceptions=NULL
 WHERE demand_id=15 AND locale='uk';

INSERT OR IGNORE INTO plan_item_translations
  (plan_item_id,locale,title,decision,instrument,owners,criterion) VALUES
 (1,'uk','Слідча комісія','Створити державну слідчу комісію щодо подій 7 жовтня.','Рішення уряду відповідно до закону про слідчі комісії.','Уряд і секретар уряду.','Рішення з предметом розслідування ухвалено й оприлюднено; суд повідомлено для призначення складу.'),
 (2,'uk','Структура уряду','Затвердити уряд не більш як із 18 міністрів і чотирьох заступників.','Коаліційна угода, рішення уряду та необхідні схвалення Кнесету.','Прем’єр-міністр, міністри юстиції та фінансів.','Оприлюднено структуру, повноваження та вартість апаратів.'),
 (3,'uk','Публікація коаліційних зобов’язань','Створити єдиний публічний реєстр коаліційних угод і пов’язаних бюджетних зобов’язань.','Рішення уряду та правила коаліції.','Секретар уряду і Міністерство фінансів.','Доступні документи, додатки, суми та відповідальні органи.'),
 (4,'uk','Рівна участь у службі','Опублікувати законопроєкт про поступове розширення військової, національної або цивільної служби за законом і перевірюваними критеріями.','Урядовий законопроєкт.','Міністерства оборони, юстиції, фінансів і соціальної політики.','Оприлюднено цілі, строки, стимули, санкції та форми цивільної служби.'),
 (5,'uk','Правила незалежності поліції','Визначити межу між загальною політикою міністра та забороненим втручанням у розслідування, протести й операції.','Рішення уряду, обов’язкова директива та, за потреби, зміни законодавства.','Міністр внутрішньої безпеки, міністр юстиції та керівництво поліції.','Оприлюднено правила й механізм скарг на політичне втручання.'),
 (6,'uk','Дотримання судових рішень','Затвердити державний протокол виконання остаточних судових рішень.','Рішення уряду та адміністративна директива.','Міністр юстиції, юридичний радник уряду та керівники міністерств.','Для кожного рішення визначено відповідальний орган і строк.'),
 (7,'uk','Призначення керівників служб безпеки','Оприлюднити єдині професійні критерії призначення керівників армії, поліції та розвідувальних служб.','Рішення уряду та необхідні законодавчі зміни.','Прем’єр-міністр і міністри оборони, юстиції та внутрішньої безпеки.','Опубліковано вимоги до досвіду, перевірку конфлікту інтересів, строк повноважень і роль комісій.'),
 (8,'uk','Прозорість додаткових бюджетів','Включити додаткові галузеві видатки до прозорої бюджетної процедури.','Бюджетні правила та, за потреби, зміни законодавства.','Міністерство фінансів і генеральний бухгалтер.','Опубліковано реєстр суми, отримувача, мети, критеріїв і показників контролю.'),
 (9,'uk','Фінансовий план війни та відновлення','Опублікувати багаторічний план оборонних видатків, відновлення постраждалих районів, підтримки резервістів і стабілізації боргу.','Бюджет і багаторічна фінансова програма.','Міністерства фінансів, оборони та економічні відомства.','Опубліковано базовий і стресовий сценарії, джерела фінансування та ключові ризики.'),
 (10,'uk','Базова освіта й зайнятість','Пов’язати державне фінансування закладів освіти з прозорістю, узгодженим ядром предметів і вимірюваними результатами.','Бюджетні умови, нормативні акти та законодавство.','Міністерства освіти, фінансів, економіки та праці.','Опубліковано поетапний план із показниками освіти та зайнятості.'),
 (11,'uk','Стабільні конституційні правила','Започаткувати парламентсько-громадський процес щодо поділу влади та змін Основних законів.','Рішення Кнесету і робота профільного комітету.','Голова Кнесету та Конституційний комітет.','Оприлюднено склад, мандат, графік і правила рішень кваліфікованою більшістю.');

