UPDATE plan_item_translations SET
 title='Призначення керівників служб безпеки', decision='Оприлюднити єдині професійні критерії призначення керівників армії, поліції та розвідувальних служб.',
 instrument='Рішення уряду та законодавчі зміни, якщо вони потрібні.', owners='Прем’єр-міністр, міністри оборони, юстиції та внутрішньої безпеки.',
 criterion='Оприлюднено вимоги до досвіду, перевірку конфлікту інтересів, строк повноважень і роль професійних комісій.'
 WHERE plan_item_id=7 AND locale='uk';
UPDATE plan_item_translations SET
 title='Прозорість додаткових бюджетів', decision='Включити додаткові галузеві видатки до прозорої бюджетної процедури.',
 instrument='Бюджетні правила та, за потреби, зміни законодавства.', owners='Міністерство фінансів і генеральний бухгалтер.',
 criterion='Опубліковано реєстр суми, отримувача, мети, критеріїв і показників контролю.'
 WHERE plan_item_id=8 AND locale='uk';
UPDATE plan_item_translations SET
 title='Фінансовий план періоду війни та відновлення', decision='Опублікувати багаторічний план оборонних видатків, відновлення постраждалих районів, підтримки резервістів і стабілізації боргу.',
 instrument='Бюджет і багаторічна фінансова програма.', owners='Міністерство фінансів, Міністерство оборони та економічні відомства.',
 criterion='Опубліковано базовий і стресовий сценарії, джерела фінансування та ключові ризики.'
 WHERE plan_item_id=9 AND locale='uk';
UPDATE plan_item_translations SET
 title='Базова освіта й зайнятість', decision='Пов’язати державне фінансування закладів освіти з прозорістю, викладанням узгодженого ядра базових предметів і вимірюваними результатами.',
 instrument='Бюджетні умови, нормативні акти та законодавство.', owners='Міністерства освіти, фінансів, економіки та праці.',
 criterion='Опубліковано поетапний план із показниками освіти та зайнятості.'
 WHERE plan_item_id=10 AND locale='uk';
UPDATE plan_item_translations SET
 title='Процес стабільних конституційних правил', decision='Започаткувати парламентсько-громадський процес щодо поділу влади та зміни Основних законів.',
 instrument='Рішення Кнесету і робота відповідного комітету.', owners='Голова Кнесету та Конституційний комітет.',
 criterion='Оприлюднено склад, мандат, графік і правила ухвалення рішень розширеною більшістю.'
 WHERE plan_item_id=11 AND locale='uk';

