INSERT OR IGNORE INTO message_templates (locale,channel,subject,body) VALUES
 ('uk','email','Особисте громадянське звернення','Вітаю, {recipient}!\n\nПрошу розглянути такі вимоги:\n{demands}\n\n{context}\n\n{name}\n{city}'),
 ('uk','whatsapp',NULL,'Вітаю, {recipient}. Моє громадянське звернення: {demands} {context}'),
 ('uk','social',NULL,'{handle}\n\nПублічно прошу:\n{demands}\n\nДолучайтеся до кампанії: {link}');
UPDATE message_templates
   SET body = replace(body, '\n', char(10)), subject = replace(subject, '\n', char(10))
 WHERE locale = 'uk';
UPDATE message_templates SET
 subject='Прошу надати чітку позицію до виборів',
 body='Вітаю.' || char(10) || char(10) ||
 'Я звертаюся до вашої партії як громадянин, який хоче отримати до виборів конкретну інформацію про її плани після голосування.' || char(10) || char(10) ||
 'Прошу відповісти на такі запитання:' || char(10) || '{demands}' || char(10) || char(10) ||
 'Бажаний формат для кожного запитання: так; ні; так, за зазначеної умови; або інше пряме пояснення.' || char(10) || char(10) ||
 'Повний текст Стандарту прозорості доступний за посиланням:' || char(10) || '{link}' || char(10) || char(10) ||
 'Повідомлення підготовлено за допомогою незалежної громадянської платформи. Платформа не рекомендує голосувати за вашу партію або проти неї.' || char(10) || char(10) ||
 'За бажання я можу передати отриману відповідь платформі для перевірки та публікації. Мої персональні дані не мають публікуватися без окремої згоди.' || char(10) || char(10) ||
 '{context}' || char(10) || char(10) || 'З повагою,' || char(10) || '{name}' || char(10) || '{city}'
 WHERE locale='uk' AND channel='email';
UPDATE message_templates SET
 body='Вітаю. Прошу надати офіційну позицію вашої партії щодо таких запитань:' || char(10) || '{demands}' || char(10) || char(10) ||
 'Бажана відповідь: «так», «ні» або «так, за умови».' || char(10) ||
 'Повний стандарт запитань: {link}' || char(10) || char(10) ||
 'Це особисте звернення громадянина. Платформа, за допомогою якої підготовлено текст, не рекомендує голосувати за будь-яку партію або проти неї.'
 WHERE locale='uk' AND channel='whatsapp';
UPDATE message_templates SET
 body='Я звернувся до {handle} із запитанням про її плани після виборів.' || char(10) || char(10) ||
 'Відповідь має бути відома до голосування, а не лише після коаліційних переговорів.' || char(10) || char(10) || '{link}'
 WHERE locale='uk' AND channel='social';

